from pathlib import Path

ROOT = Path.cwd()

FILES = {
    "app/(portal)/admin/store/actions.ts": '"use server";\n\nimport { revalidatePath } from "next/cache";\nimport { requireStaffCapability } from "@/lib/auth/require-staff";\nimport { createAdminClient } from "@/lib/supabase/admin";\n\nconst STORE_PATH = "/admin/store";\n\nfunction str(formData: FormData, key: string) {\n  return String(formData.get(key) ?? "").trim();\n}\n\nfunction nullableStr(formData: FormData, key: string) {\n  const value = str(formData, key);\n  return value || null;\n}\n\nfunction intOrNull(formData: FormData, key: string) {\n  const raw = str(formData, key);\n  if (!raw) return null;\n  const value = Number(raw);\n  if (!Number.isInteger(value)) throw new Error(`${key} must be a whole number.`);\n  return value;\n}\n\nfunction bool(formData: FormData, key: string) {\n  return formData.get(key) === "on";\n}\n\nfunction refresh() {\n  revalidatePath(STORE_PATH);\n}\n\nexport async function createStoreProduct(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const category = str(formData, "category");\n  const { error } = await admin.from("store_products").insert({\n    slug: str(formData, "slug").toLowerCase(),\n    name: str(formData, "name"),\n    description: str(formData, "description"),\n    image_url: nullableStr(formData, "image_url"),\n    category,\n    product_type: category === "bundle" ? "bundle" : "single",\n    is_active: bool(formData, "is_active"),\n    is_featured: bool(formData, "is_featured"),\n    sort_order: intOrNull(formData, "sort_order") ?? 0,\n  });\n\n  if (error) throw new Error(`Unable to create store product: ${error.message}`);\n  refresh();\n}\n\nexport async function updateStoreProduct(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n  const category = str(formData, "category");\n\n  const { error } = await admin\n    .from("store_products")\n    .update({\n      slug: str(formData, "slug").toLowerCase(),\n      name: str(formData, "name"),\n      description: str(formData, "description"),\n      image_url: nullableStr(formData, "image_url"),\n      category,\n      product_type: category === "bundle" ? "bundle" : "single",\n      is_active: bool(formData, "is_active"),\n      is_featured: bool(formData, "is_featured"),\n      sort_order: intOrNull(formData, "sort_order") ?? 0,\n    })\n    .eq("id", str(formData, "id"));\n\n  if (error) throw new Error(`Unable to update store product: ${error.message}`);\n  refresh();\n}\n\nexport async function deleteStoreProduct(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const { error } = await admin\n    .from("store_products")\n    .delete()\n    .eq("id", str(formData, "id"));\n\n  if (error) throw new Error(`Unable to delete store product: ${error.message}`);\n  refresh();\n}\n\nexport async function saveStorePrice(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const productId = str(formData, "product_id");\n  const currency = nullableStr(formData, "currency")?.toUpperCase() ?? null;\n  const moneyAmountMinor = intOrNull(formData, "money_amount_minor");\n  const remnantsAmount = intOrNull(formData, "remnants_amount");\n\n  if (moneyAmountMinor === null && remnantsAmount === null) {\n    throw new Error("Enter a real-money price, a Remnant price, or both.");\n  }\n  if (moneyAmountMinor !== null && !currency) {\n    throw new Error("Currency is required for a real-money price.");\n  }\n\n  if (currency) {\n    await admin.from("store_product_prices")\n      .delete()\n      .eq("product_id", productId)\n      .eq("currency", currency);\n  }\n\n  if (remnantsAmount !== null) {\n    await admin.from("store_product_prices")\n      .delete()\n      .eq("product_id", productId)\n      .not("remnants_amount", "is", null);\n  }\n\n  const { error } = await admin.from("store_product_prices").insert({\n    product_id: productId,\n    currency,\n    money_amount_minor: moneyAmountMinor,\n    remnants_amount: remnantsAmount,\n    paddle_price_id: nullableStr(formData, "paddle_price_id"),\n    is_active: true,\n  });\n\n  if (error) throw new Error(`Unable to save store price: ${error.message}`);\n  refresh();\n}\n\nexport async function deleteStorePrice(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const { error } = await admin\n    .from("store_product_prices")\n    .delete()\n    .eq("id", str(formData, "id"));\n\n  if (error) throw new Error(`Unable to delete store price: ${error.message}`);\n  refresh();\n}\n\nexport async function addStoreGrant(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const grantType = str(formData, "grant_type");\n  const target = str(formData, "target");\n\n  const row = {\n    product_id: str(formData, "product_id"),\n    grant_type: grantType,\n    portal_skin_id: grantType === "portal_skin" ? target : null,\n    cosmetic_item_id: grantType === "cosmetic" ? target : null,\n    feature_key: grantType === "feature" ? target : null,\n  };\n\n  const { error } = await admin.from("store_product_grants").insert(row);\n  if (error) throw new Error(`Unable to add product grant: ${error.message}`);\n  refresh();\n}\n\nexport async function deleteStoreGrant(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const { error } = await admin\n    .from("store_product_grants")\n    .delete()\n    .eq("id", str(formData, "id"));\n\n  if (error) throw new Error(`Unable to remove product grant: ${error.message}`);\n  refresh();\n}\n\nexport async function createStoreDiscount(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const discountType = str(formData, "discount_type");\n  const scopeType = str(formData, "scope_type");\n\n  const { error } = await admin.from("store_discount_codes").insert({\n    code: nullableStr(formData, "code")?.toUpperCase() ?? null,\n    name: str(formData, "name"),\n    description: str(formData, "description"),\n    discount_type: discountType,\n    discount_value: intOrNull(formData, "discount_value"),\n    currency:\n      discountType === "fixed_money"\n        ? (nullableStr(formData, "currency")?.toUpperCase() ?? "GBP")\n        : null,\n    scope_type: scopeType,\n    scope_category:\n      scopeType === "category" ? nullableStr(formData, "scope_category") : null,\n    max_redemptions: intOrNull(formData, "max_redemptions"),\n    max_redemptions_per_user:\n      intOrNull(formData, "max_redemptions_per_user") ?? 1,\n    is_public: bool(formData, "is_public"),\n    is_active: bool(formData, "is_active"),\n    starts_at: nullableStr(formData, "starts_at"),\n    ends_at: nullableStr(formData, "ends_at"),\n  });\n\n  if (error) throw new Error(`Unable to create discount: ${error.message}`);\n  refresh();\n}\n\nexport async function toggleStoreDiscount(formData: FormData) {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const { error } = await admin\n    .from("store_discount_codes")\n    .update({ is_active: str(formData, "next") === "true" })\n    .eq("id", str(formData, "id"));\n\n  if (error) throw new Error(`Unable to update discount: ${error.message}`);\n  refresh();\n}\n',
    "app/(portal)/admin/store/page.tsx": 'import { requireStaffCapability } from "@/lib/auth/require-staff";\nimport { createAdminClient } from "@/lib/supabase/admin";\nimport {\n  addStoreGrant,\n  createStoreDiscount,\n  createStoreProduct,\n  deleteStoreGrant,\n  deleteStorePrice,\n  deleteStoreProduct,\n  saveStorePrice,\n  toggleStoreDiscount,\n  updateStoreProduct,\n} from "./actions";\n\nexport const dynamic = "force-dynamic";\nexport const revalidate = 0;\n\nconst field =\n  "w-full min-w-0 border border-[rgb(var(--sep-colour-60482e))]/55 bg-[rgb(var(--sep-colour-100c09))] px-3 py-2.5 text-xs text-[rgb(var(--sep-colour-d7c4a5))] outline-none";\nconst label =\n  "mb-1 block text-[7px] uppercase tracking-[0.18em] text-[rgb(var(--sep-colour-756958))]";\nconst button =\n  "inline-flex items-center justify-center border border-[rgb(var(--sep-skin-c1,169_138_96))]/55 bg-[rgb(var(--sep-colour-21170f))] px-3 py-2 text-[8px] uppercase tracking-[0.14em] text-[rgb(var(--sep-skin-c1,169_138_96))] transition hover:border-[rgb(var(--sep-skin-c1,169_138_96))]";\nconst dangerButton =\n  "inline-flex items-center justify-center border border-red-900/55 bg-red-950/20 px-3 py-2 text-[8px] uppercase tracking-[0.14em] text-red-300";\n\nfunction moneyLabel(minor: number | null, currency: string | null) {\n  if (minor === null || !currency) return "—";\n  return new Intl.NumberFormat("en-GB", {\n    style: "currency",\n    currency,\n  }).format(minor / 100);\n}\n\nexport default async function AdminStorePage() {\n  await requireStaffCapability("character_economy");\n  const admin = createAdminClient();\n\n  const [\n    productsResult,\n    pricesResult,\n    grantsResult,\n    skinsResult,\n    cosmeticsResult,\n    discountsResult,\n  ] = await Promise.all([\n    admin.from("store_products").select("*").order("sort_order").order("name"),\n    admin.from("store_product_prices").select("*").order("created_at"),\n    admin.from("store_product_grants").select("*").order("created_at"),\n    admin.from("portal_skins").select("id, slug, name, is_active").order("name"),\n    admin.from("cosmetic_items").select("id, slug, name, category, is_active").order("category").order("name"),\n    admin.from("store_discount_codes").select("*").order("created_at", { ascending: false }),\n  ]);\n\n  for (const result of [\n    productsResult,\n    pricesResult,\n    grantsResult,\n    skinsResult,\n    cosmeticsResult,\n    discountsResult,\n  ]) {\n    if (result.error) throw new Error(result.error.message);\n  }\n\n  const products = productsResult.data ?? [];\n  const prices = pricesResult.data ?? [];\n  const grants = grantsResult.data ?? [];\n  const skins = skinsResult.data ?? [];\n  const cosmetics = cosmeticsResult.data ?? [];\n  const discounts = discountsResult.data ?? [];\n\n  const skinById = new Map(skins.map((x) => [x.id, x.name]));\n  const cosmeticById = new Map(cosmetics.map((x) => [x.id, x.name]));\n\n  return (\n    <main className="admin-compact p-5 sm:p-7 lg:p-9">\n      <div className="mx-auto max-w-7xl">\n        <p className="text-[9px] uppercase tracking-[0.28em] text-[rgb(var(--sep-colour-8c704b))]">\n          Administration\n        </p>\n\n        <h2 className="mt-2 font-serif text-4xl text-[rgb(var(--sep-skin-c1,169_138_96))]">\n          Sepulchria Store\n        </h2>\n\n        <p className="mt-3 max-w-3xl text-sm leading-7 text-[rgb(var(--sep-skin-c2,211_194_170))]">\n          Create products and bundles, choose what they unlock, set real-money\n          and Remnant prices, and manage promotion codes.\n        </p>\n\n        <section className="mt-8 border border-[rgb(var(--sep-skin-c1,169_138_96))]/35 bg-[rgb(var(--sep-colour-15100d))] p-4 sm:p-5">\n          <h3 className="font-serif text-2xl text-[rgb(var(--sep-skin-c1,169_138_96))]">\n            Create product\n          </h3>\n\n          <form action={createStoreProduct} className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">\n            <label>\n              <span className={label}>Name</span>\n              <input name="name" required className={field} />\n            </label>\n            <label>\n              <span className={label}>Slug</span>\n              <input name="slug" required placeholder="moonlit-skin" className={field} />\n            </label>\n            <label>\n              <span className={label}>Category</span>\n              <select name="category" defaultValue="cosmetic" className={field}>\n                <option value="skin">Skin</option>\n                <option value="cosmetic">Cosmetic</option>\n                <option value="friend_list">Friend List</option>\n                <option value="private_location">Private Location</option>\n                <option value="bundle">Bundle</option>\n              </select>\n            </label>\n            <label>\n              <span className={label}>Sort order</span>\n              <input name="sort_order" type="number" defaultValue="0" className={field} />\n            </label>\n\n            <label className="md:col-span-2 xl:col-span-3">\n              <span className={label}>Description</span>\n              <textarea name="description" rows={3} className={field} />\n            </label>\n\n            <label>\n              <span className={label}>Image URL</span>\n              <input name="image_url" className={field} />\n            </label>\n\n            <label className="flex items-center gap-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n              <input name="is_active" type="checkbox" defaultChecked />\n              Active\n            </label>\n\n            <label className="flex items-center gap-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n              <input name="is_featured" type="checkbox" />\n              Featured\n            </label>\n\n            <div className="md:col-span-2 xl:col-span-4">\n              <button className={button}>Create product</button>\n            </div>\n          </form>\n        </section>\n\n        <section className="mt-6">\n          <h3 className="font-serif text-2xl text-[rgb(var(--sep-skin-c1,169_138_96))]">\n            Products & bundles\n          </h3>\n\n          <div className="mt-4 space-y-4">\n            {products.map((product) => {\n              const productPrices = prices.filter((p) => p.product_id === product.id);\n              const productGrants = grants.filter((g) => g.product_id === product.id);\n\n              return (\n                <details\n                  key={product.id}\n                  className="border border-[rgb(var(--sep-skin-c1,169_138_96))]/30 bg-[rgb(var(--sep-colour-120e0b))]"\n                >\n                  <summary className="cursor-pointer px-4 py-4 sm:px-5">\n                    <div className="flex flex-wrap items-center justify-between gap-3">\n                      <div>\n                        <span className="font-serif text-xl text-[rgb(var(--sep-skin-c1,169_138_96))]">\n                          {product.name}\n                        </span>\n                        <span className="ml-3 text-[8px] uppercase tracking-[0.15em] text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                          {product.category}\n                        </span>\n                      </div>\n                      <span className="text-[8px] uppercase tracking-[0.12em] text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                        {product.is_active ? "Active" : "Hidden"}\n                      </span>\n                    </div>\n                  </summary>\n\n                  <div className="border-t border-[rgb(var(--sep-skin-c1,169_138_96))]/20 p-4 sm:p-5">\n                    <form action={updateStoreProduct} className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">\n                      <input type="hidden" name="id" value={product.id} />\n                      <label>\n                        <span className={label}>Name</span>\n                        <input name="name" defaultValue={product.name} required className={field} />\n                      </label>\n                      <label>\n                        <span className={label}>Slug</span>\n                        <input name="slug" defaultValue={product.slug} required className={field} />\n                      </label>\n                      <label>\n                        <span className={label}>Category</span>\n                        <select name="category" defaultValue={product.category} className={field}>\n                          <option value="skin">Skin</option>\n                          <option value="cosmetic">Cosmetic</option>\n                          <option value="friend_list">Friend List</option>\n                          <option value="private_location">Private Location</option>\n                          <option value="bundle">Bundle</option>\n                        </select>\n                      </label>\n                      <label>\n                        <span className={label}>Sort</span>\n                        <input name="sort_order" type="number" defaultValue={product.sort_order} className={field} />\n                      </label>\n\n                      <label className="md:col-span-2 xl:col-span-3">\n                        <span className={label}>Description</span>\n                        <textarea name="description" rows={3} defaultValue={product.description} className={field} />\n                      </label>\n\n                      <label>\n                        <span className={label}>Image URL</span>\n                        <input name="image_url" defaultValue={product.image_url ?? ""} className={field} />\n                      </label>\n\n                      <label className="flex items-center gap-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                        <input name="is_active" type="checkbox" defaultChecked={product.is_active} />\n                        Active\n                      </label>\n\n                      <label className="flex items-center gap-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                        <input name="is_featured" type="checkbox" defaultChecked={product.is_featured} />\n                        Featured\n                      </label>\n\n                      <div className="md:col-span-2 xl:col-span-4">\n                        <button className={button}>Save product</button>\n                      </div>\n                    </form>\n\n                    <div className="mt-6 grid gap-5 xl:grid-cols-2">\n                      <div className="border border-[rgb(var(--sep-skin-c1,169_138_96))]/20 p-4">\n                        <h4 className="font-serif text-lg text-[rgb(var(--sep-skin-c1,169_138_96))]">\n                          Pricing\n                        </h4>\n\n                        <div className="mt-3 space-y-2">\n                          {productPrices.map((price) => (\n                            <div key={price.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-[rgb(var(--sep-skin-c1,169_138_96))]/15 pb-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                              <span>\n                                {moneyLabel(price.money_amount_minor, price.currency)}\n                                {price.money_amount_minor !== null && price.remnants_amount !== null ? " · " : ""}\n                                {price.remnants_amount !== null ? `${price.remnants_amount} Remnants` : ""}\n                              </span>\n                              <form action={deleteStorePrice}>\n                                <input type="hidden" name="id" value={price.id} />\n                                <button className={dangerButton}>Remove</button>\n                              </form>\n                            </div>\n                          ))}\n                        </div>\n\n                        <form action={saveStorePrice} className="mt-4 grid gap-3 sm:grid-cols-2">\n                          <input type="hidden" name="product_id" value={product.id} />\n                          <label>\n                            <span className={label}>Currency</span>\n                            <input name="currency" defaultValue="GBP" maxLength={3} className={field} />\n                          </label>\n                          <label>\n                            <span className={label}>Money price in pence</span>\n                            <input name="money_amount_minor" type="number" min="0" placeholder="399 = £3.99" className={field} />\n                          </label>\n                          <label>\n                            <span className={label}>Remnants</span>\n                            <input name="remnants_amount" type="number" min="0" className={field} />\n                          </label>\n                          <label>\n                            <span className={label}>Paddle Price ID</span>\n                            <input name="paddle_price_id" placeholder="later" className={field} />\n                          </label>\n                          <div className="sm:col-span-2">\n                            <button className={button}>Save price</button>\n                          </div>\n                        </form>\n                      </div>\n\n                      <div className="border border-[rgb(var(--sep-skin-c1,169_138_96))]/20 p-4">\n                        <h4 className="font-serif text-lg text-[rgb(var(--sep-skin-c1,169_138_96))]">\n                          What this product unlocks\n                        </h4>\n\n                        <div className="mt-3 space-y-2">\n                          {productGrants.map((grant) => {\n                            const text =\n                              grant.grant_type === "portal_skin"\n                                ? `Skin · ${skinById.get(grant.portal_skin_id) ?? grant.portal_skin_id}`\n                                : grant.grant_type === "cosmetic"\n                                  ? `Cosmetic · ${cosmeticById.get(grant.cosmetic_item_id) ?? grant.cosmetic_item_id}`\n                                  : `Feature · ${grant.feature_key === "private_chat" ? "Private Location" : "Friend List"}`;\n\n                            return (\n                              <div key={grant.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-[rgb(var(--sep-skin-c1,169_138_96))]/15 pb-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                                <span>{text}</span>\n                                <form action={deleteStoreGrant}>\n                                  <input type="hidden" name="id" value={grant.id} />\n                                  <button className={dangerButton}>Remove</button>\n                                </form>\n                              </div>\n                            );\n                          })}\n                        </div>\n\n                        <div className="mt-4 grid gap-3">\n                          <form action={addStoreGrant} className="grid gap-2 sm:grid-cols-[1fr_auto]">\n                            <input type="hidden" name="product_id" value={product.id} />\n                            <input type="hidden" name="grant_type" value="portal_skin" />\n                            <select name="target" className={field}>\n                              {skins.filter((x) => x.is_active).map((skin) => (\n                                <option key={skin.id} value={skin.id}>{skin.name}</option>\n                              ))}\n                            </select>\n                            <button className={button}>Add skin</button>\n                          </form>\n\n                          <form action={addStoreGrant} className="grid gap-2 sm:grid-cols-[1fr_auto]">\n                            <input type="hidden" name="product_id" value={product.id} />\n                            <input type="hidden" name="grant_type" value="cosmetic" />\n                            <select name="target" className={field}>\n                              {cosmetics.filter((x) => x.is_active).map((item) => (\n                                <option key={item.id} value={item.id}>\n                                  {item.name} · {item.category}\n                                </option>\n                              ))}\n                            </select>\n                            <button className={button}>Add cosmetic</button>\n                          </form>\n\n                          <form action={addStoreGrant} className="grid gap-2 sm:grid-cols-[1fr_auto]">\n                            <input type="hidden" name="product_id" value={product.id} />\n                            <input type="hidden" name="grant_type" value="feature" />\n                            <select name="target" className={field}>\n                              <option value="friend_list">Friend List</option>\n                              <option value="private_chat">Private Location</option>\n                            </select>\n                            <button className={button}>Add feature</button>\n                          </form>\n                        </div>\n                      </div>\n                    </div>\n\n                    <form action={deleteStoreProduct} className="mt-5">\n                      <input type="hidden" name="id" value={product.id} />\n                      <button className={dangerButton}>Delete product</button>\n                    </form>\n                  </div>\n                </details>\n              );\n            })}\n\n            {!products.length ? (\n              <div className="border border-dashed border-[rgb(var(--sep-skin-c1,169_138_96))]/30 p-8 text-center text-sm text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                No Store products yet. Create the first one above.\n              </div>\n            ) : null}\n          </div>\n        </section>\n\n        <section className="mt-8 border border-[rgb(var(--sep-skin-c1,169_138_96))]/35 bg-[rgb(var(--sep-colour-15100d))] p-4 sm:p-5">\n          <h3 className="font-serif text-2xl text-[rgb(var(--sep-skin-c1,169_138_96))]">\n            Discount codes\n          </h3>\n\n          <form action={createStoreDiscount} className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">\n            <label>\n              <span className={label}>Name</span>\n              <input name="name" required className={field} />\n            </label>\n            <label>\n              <span className={label}>Code</span>\n              <input name="code" placeholder="SEP20" className={field} />\n            </label>\n            <label>\n              <span className={label}>Type</span>\n              <select name="discount_type" defaultValue="percentage" className={field}>\n                <option value="percentage">Percentage</option>\n                <option value="fixed_money">Fixed real money</option>\n                <option value="fixed_remnants">Fixed Remnants</option>\n              </select>\n            </label>\n            <label>\n              <span className={label}>Value</span>\n              <input name="discount_value" type="number" min="1" required className={field} />\n            </label>\n            <label>\n              <span className={label}>Currency</span>\n              <input name="currency" defaultValue="GBP" maxLength={3} className={field} />\n            </label>\n            <label>\n              <span className={label}>Scope</span>\n              <select name="scope_type" defaultValue="all" className={field}>\n                <option value="all">Everything</option>\n                <option value="category">Category</option>\n              </select>\n            </label>\n            <label>\n              <span className={label}>Category scope</span>\n              <select name="scope_category" className={field} defaultValue="">\n                <option value="">—</option>\n                <option value="skin">Skin</option>\n                <option value="cosmetic">Cosmetic</option>\n                <option value="friend_list">Friend List</option>\n                <option value="private_location">Private Location</option>\n                <option value="bundle">Bundle</option>\n              </select>\n            </label>\n            <label>\n              <span className={label}>Max total uses</span>\n              <input name="max_redemptions" type="number" min="1" className={field} />\n            </label>\n            <label>\n              <span className={label}>Max uses / user</span>\n              <input name="max_redemptions_per_user" type="number" min="1" defaultValue="1" className={field} />\n            </label>\n            <label>\n              <span className={label}>Starts</span>\n              <input name="starts_at" type="datetime-local" className={field} />\n            </label>\n            <label>\n              <span className={label}>Ends</span>\n              <input name="ends_at" type="datetime-local" className={field} />\n            </label>\n            <div className="flex flex-wrap items-end gap-4">\n              <label className="flex items-center gap-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                <input name="is_public" type="checkbox" defaultChecked />\n                Public code\n              </label>\n              <label className="flex items-center gap-2 text-xs text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                <input name="is_active" type="checkbox" defaultChecked />\n                Active\n              </label>\n            </div>\n\n            <div className="md:col-span-2 xl:col-span-4">\n              <button className={button}>Create discount</button>\n            </div>\n          </form>\n\n          <div className="mt-5 space-y-2">\n            {discounts.map((discount) => (\n              <div key={discount.id} className="flex flex-wrap items-center justify-between gap-3 border border-[rgb(var(--sep-skin-c1,169_138_96))]/20 px-3 py-3">\n                <div>\n                  <p className="text-sm text-[rgb(var(--sep-skin-c1,169_138_96))]">\n                    {discount.code ?? discount.name}\n                  </p>\n                  <p className="mt-1 text-[9px] uppercase tracking-[0.12em] text-[rgb(var(--sep-skin-c2,211_194_170))]">\n                    {discount.discount_type} · {discount.discount_value}\n                    {discount.is_active ? " · active" : " · disabled"}\n                  </p>\n                </div>\n\n                <form action={toggleStoreDiscount}>\n                  <input type="hidden" name="id" value={discount.id} />\n                  <input type="hidden" name="next" value={discount.is_active ? "false" : "true"} />\n                  <button className={button}>\n                    {discount.is_active ? "Disable" : "Enable"}\n                  </button>\n                </form>\n              </div>\n            ))}\n          </div>\n        </section>\n      </div>\n    </main>\n  );\n}\n',
}

for rel, content in FILES.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    print("wrote", rel)

admin_page = ROOT / "app/(portal)/admin/page.tsx"
if not admin_page.exists():
    raise SystemExit("Could not find app/(portal)/admin/page.tsx")

text = admin_page.read_text(encoding="utf-8")
if 'href="/admin/store"' not in text:
    anchor = '        <p className="mt-6 text-[10px] text-[rgb(var(--sep-colour-756957))]">'
    card = """        <section className="mt-4 border border-[rgb(var(--sep-skin-c1,169_138_96))]/45 bg-[rgb(var(--sep-colour-15100d))] p-5 sm:p-6">
          <p className="text-[8px] uppercase tracking-[0.24em] text-[rgb(var(--sep-skin-c2,211_194_170))]">
            Commerce
          </p>
          <h3 className="mt-2 font-serif text-2xl text-[rgb(var(--sep-skin-c1,169_138_96))]">
            Sepulchria Store
          </h3>
          <p className="mt-3 max-w-2xl text-sm leading-7 text-[rgb(var(--sep-skin-c2,211_194_170))]">
            Manage products, bundles, prices, entitlement grants and discount codes.
          </p>
          <Link
            href="/admin/store"
            className="mt-6 inline-flex items-center gap-3 border border-[rgb(var(--sep-skin-c1,169_138_96))]/60 bg-[rgb(var(--sep-colour-3b2919))] px-5 py-3 text-[10px] uppercase tracking-[0.18em] text-[rgb(var(--sep-skin-c1,169_138_96))] transition hover:border-[rgb(var(--sep-skin-c1,169_138_96))]"
          >
            Manage Store
            <span aria-hidden="true">→</span>
          </Link>
        </section>

"""
    if anchor not in text:
        raise SystemExit("Safe insertion point not found in app/(portal)/admin/page.tsx")
    text = text.replace(anchor, card + anchor, 1)
    admin_page.write_text(text, encoding="utf-8")
    print("patched app/(portal)/admin/page.tsx")
else:
    print("Store card already present")

print("Phase 2 Store Admin installed. Open /admin/store")
